PYTHONPATH=.packages python3 -c 'import json; import pandas as pd; import numpy as np; from forecast import CUTOFF, load_history, calendar_frame; from pathlib import Path; p=Path("outputs"); b=pd.read_csv(p/"backtest_predictions.csv"); m=json.loads((p/"metadata.json").read_text()); b=b[b.model=="blend"].copy(); b["error_mw"]=b.actual_mw-b.prediction_mw; b["group"]=np.where(b.stage=="calibration","calibration",np.where(b.origin.str.endswith("01-01"),"new_year","autumn")); rows=[]; pairs=[]; biases=[]
for group,g in b.groupby("group"):
    e=g.error_mw.to_numpy(); rows.append({"group":group,"hours":len(g),"coverage_at_80_band_percent":float(100*np.mean(np.abs(e)<=m["empirical_interval_half_width_80_mw"])),"coverage_at_95_band_percent":float(100*np.mean(np.abs(e)<=m["empirical_interval_half_width_95_mw"])),"abs_error_q80_mw":float(np.quantile(np.abs(e),.8,method="higher")),"mean_error_mw":float(e.mean())})
for origin,g in b.groupby("origin"):
    e=g.error_mw.to_numpy(); biases.append({"origin":origin,"group":g.group.iloc[0],"bias_actual_minus_forecast_mw":float(e.mean())}); pairs.append((e[:-1],e[1:]))
pd.DataFrame(rows).to_csv(p/"interval_diagnostics.csv",index=False); pd.DataFrame(biases).to_csv(p/"weekly_bias.csv",index=False); print(pd.DataFrame(rows).to_string(index=False)); print(pd.DataFrame(biases).to_string(index=False)); print("within_week_lag1_error_correlation",np.corrcoef(np.concatenate([a for a,c in pairs]),np.concatenate([c for a,c in pairs]))[0,1]); h=load_history(Path("opsd_de_load.csv"),CUTOFF); train=h[h.index>=CUTOFF-pd.DateOffset(years=3)]; print("last_train_calendar",calendar_frame(train.index[-2:]).to_string()); print("max_ridge_trend_extrapolation_hours",(CUTOFF+pd.Timedelta(hours=167)-train.index.max()).total_seconds()/3600); f=pd.read_csv(p/"forecast.csv"); t=pd.to_datetime(f.utc_timestamp,utc=True); assert len(f)==168 and t.is_unique and (t.diff().dropna()==pd.Timedelta(hours=1)).all(); print("verified_mean_mw",f.forecast_mw.mean(),"energy_mwh",f.forecast_mw.sum(),"peak_mw",f.forecast_mw.max(),"peak_utc",f.utc_timestamp[f.forecast_mw.idxmax()])'
